const $ = s => document.querySelector(s), ES = t => String(t == null ? '' : t).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c])); // ES: texto fixo da interface (traduzível). E: dado do usuário (protegido da tradução).
