function loginH() { return `<div class="login"><div class="brand" style="font-size:24px"><img src="/logo.png" alt="" style="width:44px"><span translate="no">Talk<b>.M3D</b></span></div><form data-f="login"><label for="em">Usuário ou e-mail</label><input id="em" type="text" autocomplete="username" autocapitalize="none" spellcheck="false" required><label for="pw">Senha</label><input id="pw" type="password" autocomplete="current-password" required>${S.err ? `<div class="err" role="alert">${ES(S.err)}</div>` : ''}<button class="pbtn">Entrar</button></form>${`<p style="text-align:center;margin-top:14px">${S.signup && S.signup !== 'off' ? 'Ainda não tem conta? <button class="lk" data-a="gosignup" style="font-size:14px">Criar conta</button>' : 'Recebeu um convite? <button class="lk" data-a="gosignup" style="font-size:14px">Usar token de convite</button>'}</p>`}</div>`; }
function signupH() { return `<div class="login"><div class="brand" style="font-size:24px"><img src="/logo.png" alt="" style="width:44px"><span translate="no">Talk<b>.M3D</b></span></div>${S.suOk ? `<div class="cd" role="status"><h3>${S.suOk === 'pendente' ? 'Cadastro enviado' : 'Conta criada'}</h3><p>${S.suOk === 'pendente' ? 'A clínica vai analisar e aprovar seu acesso. Você poderá entrar depois da aprovação.' : 'Você já pode entrar com seu e-mail e senha.' + (S.suTrial ? ' Seu período de teste vai até ' + new Date(S.suTrial).toLocaleDateString('pt-BR') + '.' : '')}</p><button class="pbtn" data-a="gologin">Ir para o login</button></div>` : `<form data-f="signup"><h2 style="margin:0">Criar conta de paciente</h2><label for="sn">Nome completo</label><input id="sn" required minlength="2" maxlength="120" autocomplete="name"><label for="se">E-mail</label><input id="se" type="email" required autocomplete="email"><label for="sp">Senha (mínimo 12 caracteres)</label><input id="sp" type="password" required minlength="12" autocomplete="new-password"><label for="st">Telefone (opcional)</label><input id="st" type="tel" maxlength="20" autocomplete="tel"><label for="sk">Token de convite (opcional)</label><input id="sk" maxlength="40" autocomplete="off" style="text-transform:uppercase" placeholder="Ex.: TALK" value="${E(S.suTok || '')}"><small class="mu">Com um token válido sua conta é liberada na hora e você ganha o período de teste ou os créditos do convite. Sem token, o cadastro pode precisar de aprovação.</small><label style="font-weight:400;display:flex;gap:8px;align-items:flex-start;margin-top:10px"><input id="sa" type="checkbox" required style="width:auto;margin-top:4px"> Li e aceito os termos de uso e a política de privacidade da clínica.</label>${S.err ? `<div class="err" role="alert">${ES(S.err)}</div>` : ''}<button class="pbtn">Criar conta</button><p class="mu">${S.signup === 'approval' ? 'Seu acesso só é liberado depois da aprovação da clínica.' : 'O e-mail ainda não é verificado: use um endereço que você controla.'}</p></form><p style="text-align:center"><button class="lk" data-a="gologin" style="font-size:14px">Já tenho conta</button></p>`}</div>`; }
document.addEventListener('submit', e => { if (e.target.dataset && e.target.dataset.f === 'signup') { e.preventDefault(); run(async () => { try { const r = await api('/signup', { m: 'POST', b: { nome: $('#sn').value.trim(), email: $('#se').value.trim(), senha: $('#sp').value, telefone: $('#st').value.trim() || undefined, token: $('#sk').value.trim() || undefined, aceite: $('#sa').checked } }); S.suOk = r.pendente ? 'pendente' : 'ok'; S.suTrial = r.teste || ''; S.err = ''; } catch (x) { S.err = x.message; } render(); }); } });
