document.addEventListener('pointerup', e => { const g = S.g; if (e.target.id !== 'g3' || !g || !g.drag) return; const moved = g.drag.m > 6; g.drag = null; if (!moved) { g.sel = gHit(e.target, e); const i = $('#g3i'); if (g.sel >= 0 && i) { const p = g.n[g.sel], nb = g.e.filter(x => x[0] === g.sel || x[1] === g.sel).map(x => g.n[x[0] === g.sel ? x[1] : x[0]].label); i.textContent = `${GN[p.type]}: ${p.label} · ${nb.length} ligações${nb.length ? ' (' + nb.slice(0, 6).join(', ') + (nb.length > 6 ? '…' : '') + ')' : ''}`; } } });
document.addEventListener('wheel', e => { if (e.target.id === 'g3' && S.g) { e.preventDefault(); S.g.zoom = Math.max(.4, Math.min(3, S.g.zoom * (e.deltaY < 0 ? 1.1 : .9))); } }, { passive: false });
S.lv = 1;
async function loadGraph() { S.gd = await api('/graph?level=' + S.lv); gInit(S.gd); if (!gl) { gl = 1; requestAnimationFrame(gDraw); } }
CENTER.grafo = () => bar('Relações (3D)') + `<div class="cv"><div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center"><span class="mu">Complexidade:</span>${['Equipe e pacientes', '+ Consultas', '+ Terapias, solicitações e atividades'].map((l, i) => `<button class="${S.lv === i + 1 ? 'pbtn' : ''}" data-a="glv" data-p="${i + 1}">${l}</button>`).join('')}</div><canvas id="g3" width="900" height="560" role="img" aria-label="Grafo 3D de relações entre equipe, pacientes, consultas, terapias e solicitações" style="width:100%;height:auto;aspect-ratio:900/560;background:var(--sf);border:1px solid var(--ln);border-radius:12px;margin-top:8px;touch-action:none;color:var(--ink)"></canvas><div class="mu lgx">${Object.keys(GC).map(k => `<i style="background:${GC[k]}"></i>${GN[k]}`).join(' ')}</div><div id="g3i" class="mu">Arraste para girar, role para aproximar e clique em um nó. Linhas mais grossas indicam mais atividades.</div></div>`;
