A.gpt = i => { const a = (S.gavg || [])[+i]; if (a) $('#gd').textContent = `Registro ${+i + 1} de 8: dor média ${a.v.toFixed(1)} (${a.n} pacientes)`; };
A.dbar = i => { const d = ((S.sh || {}).days || [])[+i]; if (d) $('#sd').textContent = `${fd(d.d)}: ${d.atendidos} atendidos, ${d.pendentes} pendentes, ${d.faltas} faltas`; };
const reTasks = async () => { S.tk = await api('/tasks'); render(); };
