document.addEventListener('dragover', e => { const c = e.target.closest && e.target.closest('[data-col]'); if (c) { e.preventDefault(); c.classList.add('ov'); } });
document.addEventListener('dragleave', e => { const c = e.target.closest && e.target.closest('[data-col]'); if (c) c.classList.remove('ov'); });
document.addEventListener('drop', e => { const c = e.target.closest && e.target.closest('[data-col]'); if (c && S.dr && S.dr.startsWith('t:')) { e.preventDefault(); c.classList.remove('ov'); const id = S.dr.slice(2); S.dr = null; run(async () => { await api('/tasks/' + id, { m: 'PATCH', b: { status: c.dataset.col } }); await reTasks(); }); } });
