/* ===== Cadastro de usuários e troca obrigatória de senha ===== */
const RL = { admin: 'Administrador', medico: 'Médico(a)', fisio: 'Fisioterapeuta', enfermeiro: 'Enfermeiro(a)', nutricionista: 'Nutricionista', farmaceutico: 'Farmácia', profissional: 'Outro profissional de saúde', cuidador: 'Cuidador(a)', recepcao: 'Secretaria / recepção', funcionario: 'Funcionário (não profissional)', paciente: 'Paciente' };
CENTER.users = function () {
  const u = S.us || [], adm = S.me.role === 'admin', opts = Object.entries(RL).filter(([k]) => adm || k === 'paciente'), pts = u.filter(x => x.role === 'paciente'), pros = u.filter(x => PRO(x.role));
  return bar('Cadastro de usuários') + `<div class="cv">${S.tmp ? `<div class="al y"><b>Senha temporária (aparece só agora):</b> <code>${E(S.tmp.pw)}</code> para ${E(S.tmp.email)}. A pessoa troca no primeiro acesso.</div>` : ''}
  ${S.regf ? regForm() : ''}<div class="cd dtt" style="margin:8px 0 12px"><h3>Novo usuário</h3><div class="fld"><div><label for="un">Nome</label><input id="un" maxlength="120"></div><div><label for="ue">E-mail</label><input id="ue" type="email"></div><div><label for="ur">Tipo</label><select id="ur">${opts.map(([k, l]) => `<option value="${k}">${l}</option>`).join('')}</select></div><div><label for="uc">Cargo (rótulo opcional)</label><input id="uc" maxlength="60" placeholder="ex.: Psicóloga"></div><div><label for="uf">Telefone (SMS)</label><input id="uf" maxlength="20"></div>${adm ? '<div><label for="uu">Usuário de login (opcional)</label><input id="uu" maxlength="30" placeholder="ex.: ana.costa" autocapitalize="none"></div>' : ''}</div><button class="pbtn" data-a="ucreate">Criar com senha temporária</button></div>
  <div class="cd dtt" style="margin-bottom:12px"><h3>Vincular paciente e profissional</h3><div class="fld"><div><label for="vp">Paciente</label><select id="vp">${pts.map(p => `<option value="${p.id}">${E(p.name)}</option>`).join('')}</select></div><div><label for="vq">Profissional / equipe</label><select id="vq">${pros.map(p => `<option value="${p.id}">${E(p.name)} · ${(p.cargo ? E(p.cargo) : ES(RL[p.role]))}</option>`).join('')}</select></div></div><button data-a="ulink">Vincular</button></div>
  <div class="wrap"><table><tr><th>Nome</th><th>Tipo</th><th>E-mail</th><th>Registro e assinatura</th><th>Situação</th><th></th></tr>${u.map(x => `<tr><td>${E(x.name)}${x.username ? ` <span class="mu">@${E(x.username)}</span>` : ''}</td><td>${(x.cargo ? E(x.cargo) : ES(RL[x.role]))}</td><td>${E(x.email)}</td><td>${x.reg_conselho ? E(x.reg_conselho + ' ' + x.reg_numero + '/' + x.reg_uf) : '–'}${x.tem_assinatura ? ' · assinatura ✓' : ''}${adm && HLT(x.role) ? ` <button class="lk" data-a="ureg" data-p="${x.id}">configurar</button>` : ''}</td><td>${x.pending ? 'Aguardando aprovação' : x.active ? 'Ativo' : 'Bloqueado'}${x.is_root ? ' · root' : ''}${x.must_change ? ' · senha temporária' : ''}${x.bloqueada ? ' · conta travada por tentativas' : ''}<br><small class="mu">${x.last_login_at ? 'Último acesso ' + new Date(x.last_login_at).toLocaleString('pt-BR') : 'Nunca acessou'}</small></td><td>${x.pending ? `<button class="pbtn" data-a="uapprove" data-p="${x.id}">Aprovar</button> <button data-a="ureject" data-p="${x.id}">Recusar</button>` : ''}${adm && !x.is_root && !x.pending ? `<button data-a="utoggle" data-p="${x.id}">${x.active ? 'Bloquear' : 'Reativar'}</button>` : ''}${adm && !x.pending ? ` <button data-a="ucred" data-p="${x.id}|reset-password">Redefinir senha</button>${x.bloqueada ? ` <button data-a="ucred" data-p="${x.id}|unlock">Destravar</button>` : ''} <button data-a="ucred" data-p="${x.id}|revoke-sessions">Encerrar sessões</button>` : ''}</td></tr>`).join('')}</table></div></div>`;
};
A.ucred = p => run(async () => { const [id, a] = p.split('|'); if (a === 'reset-password' && !confirm('Gerar uma senha temporária? A senha atual deixa de valer e as sessões abertas são encerradas.')) return; const r = await api(`/users/${id}/${a}`, { m: 'POST' }); if (r.tempPassword) { S.tmpPw = r.tempPassword; toast('Senha temporária: ' + r.tempPassword); } else toast('Feito'); await loadUs(); render(); });
