A.utoggle = id => run(async () => { const x = S.us.find(u => u.id === id); await api(`/users/${id}/active`, { m: 'PATCH', b: { active: !x.active } }); await loadUs(); render(); });
const _v2 = A.view; A.view = p => p === 'users' ? run(async () => { S.view = 'users'; S.lo = 0; S.tmp = null; await loadUs(); render(); }) : _v2(p);
